import csv
import json
import re
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-191"
OUTPUT_PATH = TASK_DIR / "computed_gt.json"


def read_json(relative_path):
    with (PACKAGE_ROOT / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(relative_path):
    return (PACKAGE_ROOT / relative_path).read_text(encoding="utf-8", errors="replace")


def load_manifest_rows():
    with (PACKAGE_ROOT / "metadata" / "files.csv").open("r", encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def first_int(pattern, text, label):
    match = re.search(pattern, text, flags=re.IGNORECASE | re.DOTALL)
    if not match:
        raise ValueError(f"Could not extract {label}")
    return int(match.group(1).replace(",", ""))


def plain_report_text(html):
    text = re.sub(r"<[^>]+>", " ", html)
    replacements = {
        "&nbsp;": " ",
        "&amp;": "&",
        "&rsquo;": "'",
        "&ldquo;": '"',
        "&rdquo;": '"',
        "&#8217;": "'",
        "&#8220;": '"',
        "&#8221;": '"',
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return re.sub(r"\s+", " ", text)


def summarize_open_meteo(daily, start, end):
    values = [
        float(precip)
        for date, precip in zip(daily["time"], daily["precipitation_sum"])
        if start <= date <= end
    ]
    return {
        "days": len(values),
        "dry_days_lt_1mm": sum(1 for value in values if value < 1.0),
        "sum_mm": round(sum(values), 3),
        "mean_mm": round(sum(values) / len(values), 3),
    }


def summarize_power(values_by_date, start, end):
    values = [
        float(value)
        for date, value in values_by_date.items()
        if start <= date <= end
    ]
    return {
        "days": len(values),
        "dry_days_lt_1mm": sum(1 for value in values if value < 1.0),
        "sum_mm": round(sum(values), 3),
        "mean_mm": round(sum(values) / len(values), 3),
    }


def ratio(numerator, denominator, digits=3):
    return round(numerator / denominator, digits)


def main():
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_2015_Southeast_Asia_haze_from_Indonesian_fires.json"
    )
    html = read_text("data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html")
    open_meteo = read_json("data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json")
    nasa_power = read_json("data/physical_hazard/physical_hazard_002_NASA_POWER_daily_weather_fill.json")
    sentinel = read_json("data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")
    manifest = load_manifest_rows()

    normalized_text = (
        plain_report_text(html)
        .replace("six-fold", "6-fold")
        .replace("three times", "3 times")
        .replace("ten times", "10 times")
    )

    psi_floor = first_int(r"PSI\).*?soared above ([\d,]+)", html, "PSI floor")
    psi_hazardous_threshold = first_int(
        r"Any score above ([\d,]+) is considered hazardous",
        html,
        "PSI hazardous threshold",
    )
    particle_factor = first_int(
        r"detected a ([\d,]+)-fold increase in particles",
        normalized_text,
        "particle factor",
    )
    peat_co_multiplier = first_int(
        r"peat fires release ([\d,]+) times as much carbon monoxide",
        normalized_text,
        "peat carbon-monoxide multiplier",
    )
    peat_methane_multiplier = first_int(
        r"and ([\d,]+) times as much methane",
        normalized_text,
        "peat methane multiplier",
    )
    calipso_height_km = first_int(r"reached ([\d,]+) kilometers?", html, "CALIPSO height")
    typical_co_ppb = first_int(r"usually about ([\d,]+) parts per billion", html, "typical carbon monoxide")
    peak_co_ppb = first_int(r"surface up to nearly ([\d,]+) parts per billion", html, "peak carbon monoxide")
    airs_height_km = first_int(r"about ([\d,]+) kilometers above the surface", html, "AIRS height")
    mls_height_km = first_int(r"upwards of ([\d,]+) kilometers in late October", html, "MLS height")

    event_start = anchor["temporal_window"]["start_date"]
    open_meteo_end = open_meteo["daily"]["time"][-1]
    power_end_raw = nasa_power["header"]["end"]
    power_end_iso = f"{power_end_raw[:4]}-{power_end_raw[4:6]}-{power_end_raw[6:]}"

    power_precip_by_date = {
        f"{date[:4]}-{date[4:6]}-{date[6:]}": value
        for date, value in nasa_power["properties"]["parameter"]["PRECTOTCORR"].items()
    }
    open_summary = summarize_open_meteo(open_meteo["daily"], event_start, open_meteo_end)
    power_summary = summarize_power(power_precip_by_date, event_start, power_end_iso)

    psi_ratio_min = ratio(psi_floor, psi_hazardous_threshold)
    surface_co_ratio = ratio(peak_co_ppb, typical_co_ppb)
    dry_day_share_open = ratio(open_summary["dry_days_lt_1mm"], open_summary["days"])
    dry_day_share_power = ratio(power_summary["dry_days_lt_1mm"], power_summary["days"])
    vertical_values = [calipso_height_km, airs_height_km, mls_height_km]
    max_vertical_signal_km = max(vertical_values)
    dnbr_counts = [sentinel["counts"]["pre_count"], sentinel["counts"]["post_count"]]

    dry_test = dry_day_share_open >= 0.30 and dry_day_share_power >= 0.30
    peat_multiplier_test = peat_co_multiplier >= 3 and peat_methane_multiplier >= 10
    peat_tests = {
        "dry_day_shares_ge_0_30": dry_test,
        "peat_multipliers_ge_3_and_10": peat_multiplier_test,
        "psi_ratio_ge_5": psi_ratio_min >= 5,
        "surface_co_ratio_ge_10": surface_co_ratio >= 10,
        "aerosol_factor_ge_5": particle_factor >= 5,
        "vertical_signal_ge_5km": max_vertical_signal_km >= 5,
    }
    peat_score = sum(1 for passed in peat_tests.values() if passed)
    rainfall_score = 1 if dry_test else 0
    burn_scar_score = 1 if all(count > 0 for count in dnbr_counts) else 0

    expected_json = {
        "psi_ratio_min": psi_ratio_min,
        "surface_co_ratio": surface_co_ratio,
        "aerosol_factor": particle_factor,
        "max_vertical_signal_km": max_vertical_signal_km,
        "dry_day_shares": {
            "open_meteo": dry_day_share_open,
            "nasa_power": dry_day_share_power,
        },
        "dnbr_pre_post_counts": dnbr_counts,
        "candidate_scores": {
            "peat_smoke": peat_score,
            "rainfall_only": rainfall_score,
            "burn_scar": burn_scar_score,
        },
        "final_label": "peat_smoke_haze_pass"
        if peat_score == 6 and rainfall_score < peat_score and burn_scar_score < peat_score
        else "ledger_not_confirmed",
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final compact ledger and label",
                "points": 3,
                "description": "Returns the requested JSON with final_label peat_smoke_haze_pass and candidate scores of 6, 1, and 0.",
                "partial_credit": "Award 1-2 points for a correct label with incomplete scores or correct scores with a missing label.",
            },
            {
                "name": "PSI and near-surface carbon-monoxide ratios",
                "points": 4,
                "description": "Computes 2000 / 350 = 5.714 and 1300 / 100 = 13.0 with correct rounding and field meanings.",
                "partial_credit": "Award 1-3 points for one correct ratio, small rounding errors, or values listed without the division logic.",
            },
            {
                "name": "Aerosol and vertical-signal values",
                "points": 3,
                "description": "Reports the 6-fold particle factor and uses the maximum of 2, 5, and 9 km as max_vertical_signal_km = 9.",
                "partial_credit": "Award 1-2 points for one correct value or for using a lower listed height while showing the right source values.",
            },
            {
                "name": "Dry-window and peat-emission tests",
                "points": 4,
                "description": "Computes 18 / 46 = 0.391, 15 / 46 = 0.326, and applies peat carbon-monoxide and methane multiplier thresholds of 3 and 10.",
                "partial_credit": "Award 1-3 points for correct dry-day counts but wrong shares, one weather product only, or multiplier values without the pass test.",
            },
            {
                "name": "Candidate-score arithmetic",
                "points": 3,
                "description": "Assigns six peat-smoke points, one rainfall-only point, and zero burn-scar points according to the stated rules.",
                "partial_credit": "Award 1-2 points for applying most tests but miscounting one candidate score.",
            },
            {
                "name": "dNBR count handling",
                "points": 2,
                "description": "Reports [0, 0] and uses those counts to give the burn-scar candidate zero points.",
                "partial_credit": "Award 1 point for listing the counts without applying the burn-scar scoring rule.",
            },
            {
                "name": "Answer discipline",
                "points": 1,
                "description": "Returns only the compact JSON object and avoids adding legal culpability, exact ignition-site claims, casualty estimates, or other quantities not produced by the ledger.",
                "partial_credit": "Award 0.5 points for minor extra wording without changing the computed answer.",
            },
        ],
    }

    answer = {
        "schema_version": "1.0",
        "task_id": "CSX-191_Q2",
        "event_id": "CSX-191",
        "task_type": "short_answer",
        "target_family": "candidate_explanation_score_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": expected_json["final_label"],
            "answer_type": "compact_json_ledger",
            "expected_json": expected_json,
            "score_rule": "six peat-smoke tests; rainfall-only gets only the dry-day point; burn-scar gets one point only when both dNBR counts are positive",
            "tolerances": {
                "ratios_and_shares": 0.005,
                "integer_fields": 0,
            },
        },
        "key_values": {
            "event_metadata": {
                "event_name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "hazard_label": event["hazard_label"],
                "temporal_window": anchor["temporal_window"],
                "location_text": anchor["spatial_window"]["location_text"],
            },
            "formula_inputs": {
                "psi_floor": psi_floor,
                "psi_hazardous_threshold": psi_hazardous_threshold,
                "typical_co_ppb": typical_co_ppb,
                "peak_co_ppb_nearly": peak_co_ppb,
                "particle_factor": particle_factor,
                "peat_co_multiplier": peat_co_multiplier,
                "peat_methane_multiplier": peat_methane_multiplier,
                "vertical_signal_km_values": vertical_values,
                "dnbr_pre_post_counts": dnbr_counts,
            },
            "daily_weather_windows": {
                "open_meteo": {
                    "start": event_start,
                    "end": open_meteo_end,
                    **open_summary,
                    "dry_day_share": dry_day_share_open,
                },
                "nasa_power": {
                    "start": event_start,
                    "end": power_end_iso,
                    **power_summary,
                    "dry_day_share": dry_day_share_power,
                },
            },
            "pass_tests": peat_tests,
            "candidate_scores": expected_json["candidate_scores"],
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "metadata/files.csv",
                "data/event_reports/event_reports_003_Locked_event_anchor_2015_Southeast_Asia_haze_from_Indonesian_fires.json",
                "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html",
                "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
                "data/physical_hazard/physical_hazard_002_NASA_POWER_daily_weather_fill.json",
                "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
            ],
            "manifest_success_file_count": sum(
                1
                for row in manifest
                if row["file_status"] in {"success", "downloaded", "remote_verified", "local_file_found"}
            ),
        },
    }

    OUTPUT_PATH.write_text(json.dumps(answer, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
